'use strict';
// Edice 04: decisions, outcomes and market pressure use the same weekly ledger.
const V3={fresh,makeStore,nextWeek,validateSave,simulateRivals,demandForStore,autoManager,roastBatch,getBeanCost,weeklyFixed,proposal,person3,openStore,updateBlend,cityStock,trainPerson};
const ECONOMY4={growth:{name:'Růst trhu',demand:1.04,input:1,rent:1.02},steady:{name:'Stabilní trh',demand:1,input:1.05,rent:1.03},inflation:{name:'Drahé vstupy',demand:.97,input:1.18,rent:1.07},recession:{name:'Slabší poptávka',demand:.86,input:1.08,rent:1.02}};
const TRAITS4={coach:'Mentor týmu',artisan:'Kávový specialista',ambitious:'Ambiciózní lídr',operator:'Provozní analytik'};
const RIVAL4={daily:{ceo:'Marek Steiner',focus:'volume',title:'Objem a městská dominance'},atelier:{ceo:'Camille Laurent',focus:'quality',title:'Prémiové adresy a kvalita'},north:{ceo:'Sofia Berg',focus:'wholesale',title:'Komunitní síť a velkoobchod'}};
function person4(p){if(!p)return p;p=V3.person3(p);if(!p.life)p.life={trait:p.trait==='Výroba a logistika'||p.strength.product>p.strength.people+1?'artisan':p.ambition>=65||p.trait==='Hosté a značka'?'ambitious':p.strength.people>=88?'coach':'operator',burnout:0,lastStory:0,promotionDue:0,breakUntil:0};return p;}
function store4(s){store3(s);if(!s.lease)s.lease={rent:loc(s.id).rent,due:state.week+26,renewals:0};if(!s.operations){s.operations={wait:0,occupied:0,stockLost:0,capacityLost:0,visitors:0,served:0};if(s.last)operations4(s);}if(s.manager)s.manager=person4(s.manager);return s;}
function ensure4(v){const previous=state;try{state=v;v.version=4;v.empire=v.empire||{cycle:'growth',nextCycle:v.week+13,markets:{},plans:[],planHistory:[],trials:[],stories:[],storyHistory:[],partnership:null,publicCompany:null,covenant:null,autoPlans:false,planLimit:75000,pendingExpense:0,decisionHistory:[],lastQuarter:0};v.stores.forEach(store4);for(const a of staffAssignments())a.entity.manager=person4(a.person);v.talents=v.talents.map(person4);for(const r of v.rivals){if(!r.business)r.business={focus:RIVAL4[r.id]?.focus||'volume',quality:r.strategy==='quality'?88:72,accounts:0,accountCapacity:3,expansionDue:v.week+difficulty3().rivalEvery*2,decisions:[],campaign:null,investment:0,reserved:0};}for(const b of [...v.batches,...v.transfers.flatMap(t=>t.batches)]){const recipe=blend(b.blend);b.profile=b.profile||{roast:recipe.roast,primary:recipe.primary,secondary:recipe.secondary,share:recipe.share};}return v;}finally{state=previous}}
fresh=function(...args){return ensure4(V3.fresh(...args))};
makeStore=function(...args){return store4(V3.makeStore(...args))};
person3=function(m){return person4(V3.person3(m))};
state=ensure4(state);
function economy4(){return ECONOMY4[state.empire.cycle]}
function cityPressure4(city){const locations=LOCATIONS.filter(l=>l.city===city),player=state.stores.filter(s=>loc(s.id).city===city).length,rivals=state.rivals.filter(r=>!r.bankrupt).reduce((a,r)=>a+r.stores.filter(id=>loc(id).city===city).length,0),occupancy=(player+rivals)/Math.max(1,locations.length);return {player,rivals,occupancy,factor:clamp(1.03-occupancy*.16,.84,1.03)};}
function overhead4(){const n=state.stores.filter(s=>!s.franchise).length,coordination=n<=4?0:(n-4)*3900*(1+Math.log2(Math.max(1,n/4))*.25),support=clamp(1-state.departments.it*.045-state.regions.length*.035,.55,1);return round(coordination*support)}
function updateEconomy4(){if(state.week>=state.empire.nextCycle){const keys=['growth','steady','inflation','recession'];state.empire.cycle=keys[(keys.indexOf(state.empire.cycle)+1)%keys.length];state.empire.nextCycle=state.week+13;log('Trh: '+economy4().name,'Poptávka '+round(economy4().demand*100)+' %, vstupy '+round(economy4().input*100)+' %. Další změna za 13 týdnů.');}for(const c of CITIES)state.empire.markets[c.name]=cityPressure4(c.name);for(const s of state.stores){store4(s);if(typeof propertyAutoLease5==='function'&&propertyAutoLease5(s))continue;if(state.week>=s.lease.due){if(typeof districtLeaseAdjustment6==='function')districtLeaseAdjustment6(s);s.lease.rent=round(s.lease.rent*(economy4().rent+cityPressure4(loc(s.id).city).occupancy*.025));s.lease.due=state.week+26;s.lease.renewals++;log('Obnoven nájem: '+loc(s.id).name,money(s.lease.rent)+'/týden, další jednání v týdnu '+s.lease.due+'.');}}}
getBeanCost=function(origin){return V3.getBeanCost(origin)*economy4().input};
weeklyFixed=function(){return V3.weeklyFixed()+overhead4()+state.stores.filter(s=>!s.franchise).reduce((a,s)=>a+(typeof premisesFixedAdjustment5==='function'?premisesFixedAdjustment5(s):Math.max(0,(s.lease?.rent||loc(s.id).rent)-loc(s.id).rent)),0)};
function blendFit4(s){const city=loc(s.id).city,local=state.batches.filter(b=>b.blend===s.blend&&(b.zone===city||state.deliveryPolicy==='express')),kg=local.reduce((a,b)=>a+b.kg,0),target=loc(s.id).segment==='specialty'||loc(s.id).segment==='tourist'?1:loc(s.id).segment==='community'?2:3;return kg?clamp(local.reduce((a,b)=>a+b.kg*(1-Math.abs((b.profile?.roast||blend(s.blend).roast)-target)*.025),0)/kg,.91,1.03):1;}
demandForStore=function(s,factor){const d=V3.demandForStore(s,factor),market=cityPressure4(loc(s.id).city),life=s.manager?.life,breakFactor=life?.breakUntil>=state.week ? .94 : 1,campaign=state.rivals.filter(r=>!r.bankrupt&&r.business.campaign?.city===loc(s.id).city&&r.business.campaign.until>=state.week).reduce((a,r)=>a*.96,1),fit=blendFit4(s);d.demand=round(d.demand*economy4().demand*market.factor*campaign*fit*(typeof seasonDemandFactor5==='function'?seasonDemandFactor5(s):1)*(typeof premisesDemand5==='function'?premisesDemand5(s):1)*(typeof districtDemand6==='function'?districtDemand6(s):1));d.potential=d.menu?.hasDrinks===false?0:Math.min(d.demand,round((d.capacity??d.potential)*breakFactor));d.ingredientCost*=economy4().input;d.extraCosts+=typeof premisesRentExtra5==='function'?premisesRentExtra5(s):Math.max(0,s.lease.rent-loc(s.id).rent);if(life?.trait==='coach'){d.morale=clamp(d.morale+3,0,100);s.quality=clamp(s.quality+1,15,99);}d.market={factor:market.factor,macro:economy4().demand,fit,campaign};return d;};
roastBatch=function(r,b,kg,emergency=false){const count=state.batches.length,result=V3.roastBatch(r,b,kg,emergency);for(const lot of state.batches.slice(count)){lot.profile={roast:b.roast,primary:b.primary,secondary:b.secondary,share:b.share};if(r.manager?.life?.trait==='artisan')lot.quality=clamp(lot.quality+2,0,99)}return result};
trainPerson=function(...args){const cost=state.departments.hr?12000:18000;const result=V3.trainPerson(...args);state.empire.pendingExpense+=cost;return result};
updateBlend=function(id,data){const b=blend(id),changed=b&&['primary','secondary','share','roast'].some(k=>b[k]!==data[k]);const result=V3.updateBlend(id,data);if(changed)delete b.signature;return result};
function measureStore4(s){return {guests:s.last?.served||0,lostRate:(s.last?.lost||0)/Math.max(1,(s.last?.served||0)+(s.last?.lost||0)),quality:s.quality,loyalty:s.loyalty,profit:s.last?.profit||0};}
function planAction4(s){const baseline=measureStore4(s);if(baseline.lostRate>.08&&s.last?.reason.includes('Zásoby')){const r=state.roasters.find(r=>r.zone===loc(s.id).city)||state.roasters[0];if(r?.shifts===1)return {kind:'shift',target:r.id,title:'Pokrýt odběr druhou směnou',cost:0,weekly:Math.max(0,4-r.staff)*r.wage,metric:'lostRate',targetValue:baseline.lostRate*.65};}if(baseline.lostRate>.08){if(!s.equipment.bar)return {kind:'equipment',target:'bar',title:'Zrychlit výdej přestavbou baru',cost:EQUIPMENT.bar.cost,weekly:EQUIPMENT.bar.maintenance,metric:'lostRate',targetValue:baseline.lostRate*.7};if(s.staff<7)return {kind:'staff',target:s.staff+1,title:'Posílit směnu dalším baristou',cost:0,weekly:s.wage,metric:'lostRate',targetValue:baseline.lostRate*.65};}if(s.quality<82)return {kind:'training',target:s.manager.pid,title:'Zvýšit kvalitu školením produktu',cost:state.departments.hr?12000:18000,weekly:0,metric:'quality',targetValue:Math.min(99,s.quality+2)};if(s.loyalty<55&&s.marketing<s.budget)return {kind:'marketing',target:Math.min(s.budget,s.marketing+1000),title:'Vybudovat pravidelnou klientelu',cost:0,weekly:Math.min(s.budget,s.marketing+1000)-s.marketing,metric:'loyalty',targetValue:Math.min(80,s.loyalty+3)};return null;}
function generatePlans4(){for(const s of state.stores){if(!s.manager||!s.last||s.franchise||state.empire.plans.length>=4||state.empire.plans.some(p=>p.store===s.id)||state.empire.planHistory.some(p=>p.store===s.id&&state.week-p.closed<8))continue;const action=planAction4(s);if(!action)continue;state.empire.plans.push({id:uid('plan'),pid:s.manager.pid,name:s.manager.name,store:s.id,action,baseline:measureStore4(s),status:'proposed',created:state.week,due:state.week+3,samples:[],dueReview:0,previousAuto:null});log('Návrh vedení: '+loc(s.id).name,action.title+'. Investice '+money(action.cost)+', navíc '+money(action.weekly)+'/týden.');}}
function decidePlan4(id,approve,automatic=false){guard();const p=state.empire.plans.find(p=>p.id===id),s=p&&state.stores.find(s=>s.id===p.store);if(!p||p.status!=='proposed'||!s)throw Error('Návrh už není aktuální.');if(!approve){p.status='declined';p.closed=state.week;state.empire.planHistory.unshift(p);state.empire.planHistory=state.empire.planHistory.slice(0,40);state.empire.plans=state.empire.plans.filter(x=>x!==p);log('Návrh vedení odmítnut',loc(s.id).name+' · '+p.action.title);return;}if(!s.manager||s.manager.pid!==p.pid)throw Error('Autor návrhu už tuto kavárnu nevede.');const a=p.action;if(state.cash<a.cost+a.weekly*2)throw Error('Plán nemá krytí investice a dvou týdnů nových nákladů.');if(a.kind==='equipment'){if(s.equipment[a.target])throw Error('Zařízení už bylo pořízeno.');buyEquipment(s.id,a.target)}else if(a.kind==='staff'){if(s.staff!==a.target-1)throw Error('Velikost týmu se změnila. Nech připravit nový návrh.');p.previousAuto=s.auto.staff;s.auto.staff=false;s.staff=a.target;}else if(a.kind==='shift'){const r=state.roasters.find(r=>r.id===a.target);if(!r||r.shifts!==1)throw Error('Výrobní plán se změnil. Nech připravit nový návrh.');r.shifts=2;r.staff=Math.max(4,r.staff);}else if(a.kind==='training')trainPerson(p.pid,'product');else if(a.kind==='marketing'){if(s.marketing!==a.target-a.weekly)throw Error('Marketingový rozpočet se změnil. Nech připravit nový návrh.');p.previousAuto=s.auto.marketing;s.auto.marketing=false;s.marketing=a.target;}p.status='active';p.approved=state.week;p.dueReview=state.week+4;p.automatic=automatic;log('Schválen plán: '+loc(s.id).name,a.title+' · vyhodnocení v týdnu '+p.dueReview+'.');}
function reviewPlans4(){for(const p of [...state.empire.plans]){const s=state.stores.find(s=>s.id===p.store);if(p.status==='proposed'){if(state.week>p.due){decidePlan4(p.id,false);continue;}if(state.empire.autoPlans&&p.action.cost<=state.empire.planLimit&&state.cash>weeklyFixed()*3+p.action.cost+p.action.weekly*3){try{decidePlan4(p.id,true,true)}catch{}}continue;}if(!s)continue;p.samples.push(measureStore4(s));p.samples=p.samples.slice(-4);if(state.week>=p.dueReview){const key=p.action.metric,actual=p.samples.reduce((a,m)=>a+m[key],0)/Math.max(1,p.samples.length);p.actual=actual;p.success=key==='lostRate'?actual<=p.action.targetValue:actual>=p.action.targetValue;p.status='reviewed';p.closed=state.week;if(p.previousAuto!==null){if(p.action.kind==='staff'&&s.staff===p.action.target)s.auto.staff=p.previousAuto;if(p.action.kind==='marketing'&&s.marketing===p.action.target)s.auto.marketing=p.previousAuto;}state.trust=clamp(state.trust+(p.success?2:-2),10,99);state.empire.planHistory.unshift(p);state.empire.plans=state.empire.plans.filter(x=>x!==p);log((p.success?'Splněn':'Nesplněn')+' plán: '+loc(s.id).name,p.action.title+' · výsledek '+(key==='lostRate'?round(actual*100)+' %':round(actual))+'.');}}state.empire.planHistory=state.empire.planHistory.slice(0,40)}
proposal=function(type){const p=V3.proposal(type),reviews=state.empire.planHistory.filter(p=>p.status==='reviewed').slice(0,8);if(type==='expansion'&&reviews.length>=3){const ratio=reviews.filter(p=>p.success).length/reviews.length;if(ratio<.5){p.votes[1]={name:'Jana · provoz',yes:false,reason:'Vedení splnilo jen '+reviews.filter(p=>p.success).length+' z '+reviews.length+' posledních plánů. Nejdřív stabilizuj provoz.'};}}if(state.empire.publicCompany&&type==='dividend'&&state.history.at(-1)?.margin<.1)p.votes[0]={name:'Petr · finance',yes:false,reason:'Veřejná firma potřebuje alespoň 10 % provozní marži před dividendou.'};p.passed=p.votes.filter(v=>v.yes).length>=2;return p;};
function rivalProjection4(r,l){const b=r.business,price=l.ideal*r.priceFactor,match=b.focus==='quality'?(l.segment==='specialty'||l.segment==='tourist'?1.13:.95):b.focus==='volume'?(l.segment==='office'||l.segment==='student'?1.12:1):1,traffic=l.traffic*clamp(1+(r.reputation-50)/180+(b.quality-75)/220-(r.priceFactor-1)*1.2,.4,1.45)*cityPressure4(l.city).factor*economy4().demand*match*clamp(1-Math.max(0,r.stores.filter(id=>loc(id).city===l.city).length-1)*.035,.78,1),staff=Math.ceil(l.traffic/420),sales=traffic*price,cost=traffic*(b.focus==='quality'?25:21)*economy4().input+l.rent*(1+Math.floor(state.week/26)*.04)+staff*6500+19000+(b.focus==='quality'?6000:2500);return {profit:round(sales-cost),sales:round(sales),traffic:round(traffic),fixed:l.rent+staff*6500+19000};}
function rivalDecision4(r,text,detail){const d={week:state.week,text,detail};r.business.decisions.unshift(d);r.business.decisions=r.business.decisions.slice(0,12);log(r.name+': '+text,detail)}
function simulateStrategicRivals4(){for(const r of state.rivals){if(r.bankrupt)continue;const b=r.business;let profit=r.stores.reduce((a,id)=>a+rivalProjection4(r,loc(id)).profit,0)+b.accounts*(b.focus==='wholesale'?10500:6500)-12000-r.debt*.002;profit-=Math.max(0,r.stores.length-5)*3500;r.lastProfit=round(profit);r.cash+=profit;r.history.push({week:state.week,profit:r.lastProfit,stores:r.stores.length});r.history=r.history.slice(-16);if(r.cash<0){r.bankrupt=true;r.stores=[];rivalDecision4(r,'Platební neschopnost','Ztrátový provoz vyčerpal vlastní hotovost.');continue;}if(b.campaign?.until<state.week)b.campaign=null;if(state.week<b.expansionDue)continue;b.expansionDue=state.week+difficulty3().rivalEvery*2;const weakest=state.stores.filter(s=>s.last).sort((a,b)=>(b.last.lost/Math.max(1,b.last.served+b.last.lost))-(a.last.lost/Math.max(1,a.last.served+a.last.lost)))[0],home=weakest&&r.stores.some(id=>loc(id).city===loc(weakest.id).city);if(home&&weakest.last.lost>weakest.last.served*.18&&r.cash>180000&&!b.campaign){const campaignCost=18000;r.cash-=campaignCost;b.campaign={city:loc(weakest.id).city,until:state.week+3};rivalDecision4(r,'Zaměření na nespokojené hosty',b.campaign.city+' · rival investoval '+money(campaignCost)+' do třítýdenní kampaně.');}if(b.focus==='volume')r.priceFactor=home&&r.cash>300000?.87:.94;else if(b.focus==='quality')r.priceFactor=1.14;else r.priceFactor=home?.98:1.03;
const reserve=r.stores.reduce((a,id)=>a+rivalProjection4(r,loc(id)).fixed,0)*5+(b.reserved||0)+180000;if(b.focus==='wholesale'&&b.accounts<b.accountCapacity&&r.cash>reserve+65000){r.cash-=65000;b.accounts++;rivalDecision4(r,'Nový velkoobchodní odběratel','Investice 65 000 Kč. Aktivních odběratelů '+b.accounts+', čistý týdenní přínos 10 500 Kč.');continue;}if(b.focus==='wholesale'&&b.accounts===b.accountCapacity&&b.accountCapacity<12&&r.cash>reserve+360000){r.cash-=360000;b.accountCapacity+=3;b.investment+=360000;rivalDecision4(r,'Rozšíření obchodního zázemí','Kapacita dalších tří odběratelů. Investice 360 000 Kč.');continue;}const candidates=LOCATIONS.filter(l=>!owned(l.id)&&!occupant(l.id)&&!state.auctions.some(a=>!a.closed&&a.location===l.id)&&!state.market3.exclusive.some(e=>e.location===l.id&&e.until>=state.week)&&CITIES.find(c=>c.name===l.city).unlock<=r.stores.length&&CITIES.find(c=>c.name===l.city).reputation<=r.reputation&&r.cash>l.setup+(r.stores.some(id=>loc(id).city===l.city)?42000:362000)+reserve).map(l=>{const q=rivalProjection4(r,l),focus=b.focus==='quality'&&['specialty','tourist'].includes(l.segment)?1.3:b.focus==='volume'&&['office','student'].includes(l.segment)?1.25:1,weak=weakest&&loc(weakest.id).city===l.city?1.12:1;return {l,q,score:q.profit/l.setup*focus*weak}}).filter(x=>x.q.profit>7000).sort((a,b)=>b.score-a.score);if(candidates[0]&&r.stores.length<28){const {l,q}=candidates[0],investment=l.setup+(r.stores.some(id=>loc(id).city===l.city)?42000:362000);r.cash-=investment;b.investment+=investment;r.stores.push(l.id);rivalDecision4(r,'Otevření: '+l.city+' · '+l.name,'Odhad zisku '+money(q.profit)+'/týden, návratnost '+Math.ceil(investment/q.profit)+' týdnů. Investice do adresy, náboru a výrobního zázemí '+money(investment)+'.');}else if(b.quality<95&&r.cash>reserve+60000){r.cash-=60000;b.quality+=2;r.reputation=clamp(r.reputation+1,20,95);rivalDecision4(r,'Zlepšení produktu a servisu','Investice 60 000 Kč; kvalita +2. Trh nenabízí přijatelnou návratnost další adresy.');}else rivalDecision4(r,'Udržet hotovostní rezervu','Dostupné adresy nesplnily očekávaný zisk a rozpočtovou rezervu.');r.reputation=clamp(r.reputation+(profit>0?.2:-.4),20,95);}
if(state.week%16===0&&!state.buyout){const r=state.rivals.filter(r=>!r.bankrupt&&r.cash>1500000).sort((a,b)=>b.cash-a.cash)[0];if(r)state.buyout={rival:r.id,amount:round(Math.min(companyValue()*1.12,r.cash*.6)),due:state.week+3};}if(state.buyout?.due<state.week)state.buyout=null;
if(state.week%12===0){const r=state.rivals.find(r=>!r.bankrupt&&r.business.focus==='quality'&&r.cash>450000);if(r&&!state.market3.exclusive.some(e=>e.origin)){r.cash-=45000;state.market3.exclusive.push({origin:'ethiopia',holder:r.id,until:state.week+12});rivalDecision4(r,'Prioritní sklizeň Etiopie','Investice 45 000 Kč. Běžné nákupy původu jsou na 12 týdnů dražší o 12 %.');}}
if(state.week%20===0&&!state.empire.partnership){const r=state.rivals.find(r=>!r.bankrupt&&r.business.focus==='wholesale'&&r.cash>250000);if(r)state.empire.partnership={id:uid('partnership'),rival:r.id,kg:35,price:620,due:state.week+3,blend:state.blends[0].id};}if(state.empire.partnership?.due<state.week)state.empire.partnership=null;}
simulateRivals=function(){return simulateStrategicRivals4()};
function acceptPartnership4(){guard();const p=state.empire.partnership,r=p&&state.rivals.find(r=>r.id===p.rival);if(!p||p.due<state.week||!r||r.bankrupt)throw Error('Nabídka není aktuální.');if(state.contracts.length>=state.departments.sales)throw Error('Obchod potřebuje volného člověka pro dalšího odběratele.');state.contracts.push({id:uid('contract'),name:r.name+' · partnerský odběr',blend:p.blend,kg:p.kg,price:p.price,remaining:12,fulfilled:0,last:null,buyer:r.id});state.empire.partnership=null;log('Partnerství: '+r.name,p.kg+' kg/týden po 12 týdnů za '+money(p.price)+'/kg. Odběratel platí ze své hotovosti.');}
